package com.robot.platform.ai.live;import com.robot.platform.ai.model.chat.deepseek.*;import com.robot.platform.ai.model.client.*;import com.robot.platform.ai.model.client.event.ProviderEvent;import org.junit.jupiter.api.Test;import java.util.*;import java.util.concurrent.*;import static org.junit.jupiter.api.Assertions.*;class DeepSeekChatLiveTest{@Test void streamsTextFromLiveProvider()throws Exception{String key=LiveTestGate.require("DEEPSEEK_API_KEY");var client=new DeepSeekChatModelClient(new DeepSeekSseDecoder());var model=new ResolvedModel(1,1,1,"DEEPSEEK","CHAT",System.getenv().getOrDefault("DEEPSEEK_MODEL","deepseek-chat"),System.getenv().getOrDefault("DEEPSEEK_BASE_URL","https://api.deepseek.com"),"{}","{}",key);CountDownLatch text=new CountDownLatch(1),done=new CountDownLatch(1);ChatStream stream=client.stream(new ChatRequest(model,List.of(new ChatRequest.ChatMessage("user","Reply with OK."))),e->{if(e instanceof ProviderEvent.TextDelta)text.countDown();if(e instanceof ProviderEvent.TextDone)done.countDown();});try{assertTrue(text.await(20,TimeUnit.SECONDS));assertTrue(done.await(20,TimeUnit.SECONDS));}finally{stream.close();}}}